$_MODULE['<{sudemi}prestashop>sudemi_79b0f6d2990d85e793870809766304aa'] = 'طلب المشتري إرجاع هذا الطلب. اقبل، أو ارفض مع ذكر السبب (سيراه المشتري). إذا لم ترد قبل التاريخ أدناه، يقرر sudemi. بعد القبول، استرد مبلغ هذا الطلب عند عودة المنتج.';
$_MODULE['<{sudemi}prestashop>sudemi_e00c83de07e4077ccea2be7df460c7de'] = 'بدأت مزامنة الكتالوج وتعمل في الخلفية؛ سيُرسل الكتالوج خلال بضع دقائق.';
