$_MODULE['<{sudemi}prestashop>sudemi_25f30b7a6c8492438cff249034c6a8ad'] = 'يدفع المشترون بهذه العملة، والطلبات التي يرسلها إليك sudemi تكون بها. يصلك تحويل مستحقاتك من sudemi باليورو؛ ومع أي عملة أخرى يخصم مزوّد الدفع Stripe رسوم تحويل العملة بنحو 2 بالمئة من تحويلك.';
$_MODULE['<{sudemi}prestashop>sudemi_1d75c6794f7c6f15f9d20716a7534e15'] = 'لا يقبل sudemi الدفع بعملة %1$s، لذلك لا تُعرض منتجاتك على المشترين. يقبل sudemi هذه العملات: %2$s. اختر إحداها عملةً افتراضية لهذا المتجر، ثم أرسل الكتالوج مرة أخرى.';
$_MODULE['<{sudemi}prestashop>sudemi_a0e397dee2f1c5834ab1d445aec6cdc6'] = 'يبيع هذا المتجر الآن بعملة %1$s، لكن sudemi ما زال يسجل %2$s. أرسل الكتالوج مرة أخرى ليرى المشترون الأسعار الصحيحة.';

